export const meta = {
  name: 'chain-AAAB',
  description: 'RUN-0001 stage 1 (AAAB): fix and verify B2+B3 in shelf/books.py',
  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const PARKED = { type: 'object', properties: { question: {type:'string'}, header: {type:'string', maxLength: 8},
  options: {type:'array', minItems: 2, maxItems: 4, items: {type:'object', properties: {label:{type:'string'}, does:{type:'string'}, hurts:{type:'string'}}}},
  recommended: {type:'string'}, default: {type:'string'}, reason: {enum: ['taste','fact','conflict']},
  genuine: {type:'boolean'}, gated: {type:'string'}, files: {type:'array', minItems: 1, items: {type:'string'}},
  done: {type:'string'}, stop: {enum: ['none','destructive','security','outside','scope','repro']} },
  required: ['question','header','options','default','reason','genuine','gated','files','stop'] }
const VERDICT = { type: 'object', properties: {
  ticket: {type:'string'}, passed: {type:'boolean'}, why: {type:'string'},
  evidence: {type:'string', description: 'the check that ran: exact command and its result'},
  files: {type:'array', items: {type:'string'}}, parked: PARKED },
  required: ['ticket','passed','why','evidence','files'] }
const ADD = 'If the report says PARKED: check that the independent part works, check (git diff) that the gated files hold no partial guess, judge whether the decision is genuinely the user\'s, and list every file the gated part would touch; `parked.files` is the union of yours and the fixer\'s.'
return await pipeline(args.items,
  it => agent(`${args.header}\n\n${it.text}`, { label: `AAAB fix:${it.id}`, phase: 'Fix' }),
  (report, it) => agent(`${args.header}\n\nYou are the VERIFY agent for ${it.id}. Do not edit any file. The fixer was given:\n${it.text}\n\nThe fixer reported:\n${report}\n\nIndependently check the change: read the diff (git -C "<worktree>" diff), run the test suite by absolute path, and try the ticket's exact repro with python -c. passed=true only if a check you ran shows the ticket fixed and nothing else broke. ${ADD}`,
    { label: `AAAB verify:${it.id}`, phase: 'Verify', schema: VERDICT }),
)

